Source: saved raw-pair and lift rankings. Low-rated reviews only; lift results pass q &lt; 0.05, lift &gt; 1.15, and at least 30 observed co-mentions.

Lift divides observed co-mentions by the average expected under shuffled topic assignments. The comparison preserves topic frequencies within groups originally mentioning two, three, four or five-plus topics. It helps account for popular topics and the greater pairing opportunities in multi-topic accounts. It does not hold word length or every shuffled row’s topic count fixed.
The statistical screen retains 31 of 353 tested pairs, linking 27 of the 29 taxonomy topics. Eight groups organize those connections. Use them as a guide to related material, then inspect the individual links. A cross-group connection may point to another relevant participant in a particular investigation; it does not automatically assign shared ownership.

Explore the topic-pair map The network shows each retained pair as a line: thicker lines mean a higher lift, and larger dots mean more retained pairs. Hover a topic to see its partners. The matrix view shows the same pairs as cells; pale cells have no displayed qualifying pair, not a measured zero association. Neither view has a direction of travel.

viewof mapMode = Inputs.radio(["Network", "Matrix"], {label: "View", value: "Network"})







viewof bundleView = themedSelect(["All groups", ...topicBundles.map(d=&gt;d.name)], {label:"Topic group", value:"All groups"})







mapTopics = bundleView === "All groups" ? topicOrder : topicBundles.find(d=&gt;d.name===bundleView).topics







bundleColors = {
  const hues = ["#4c78a8", "#e0823d", "#54a24b", "#d9534f", "#5fb3b3", "#9c6fb6", "#d4a017", "#8c6d5a"];
  return new Map(topicBundles.map((b, i) =&gt; [b.name, hues[i % hues.length]]));
}







topicNetwork = {
  const bundleOf = new Map(topicBundles.flatMap(b =&gt; b.topics.map(t =&gt; [t, b.name])));
  const seen = new Set(), links = [];
  for (const r of pairMatrix) {
    const key = [r.a, r.b].sort().join("|");
    if (seen.has(key)) continue;
    seen.add(key);
    links.push({source: r.a, target: r.b, lift: r.lift, same: r.same_bundle});
  }
  const degree = new Map();
  links.forEach(l =&gt; { degree.set(l.source, (degree.get(l.source) || 0) + 1); degree.set(l.target, (degree.get(l.target) || 0) + 1); });
  // Start each group on its own spot around a circle so the layout is the same on every load.
  const groups = topicBundles.map(b =&gt; b.name);
  const nodes = topicOrder.map((t, i) =&gt; {
    const g = groups.indexOf(bundleOf.get(t)), a = (g / groups.length) * 2 * Math.PI;
    return {id: t, bundle: bundleOf.get(t), degree: degree.get(t) || 0, x: Math.cos(a) * 200 + (i % 3) * 8, y: Math.sin(a) * 150 + (i % 2) * 8};
  });
  const sim = d3.forceSimulation(nodes)
    .force("link", d3.forceLink(links).id(d =&gt; d.id).distance(l =&gt; l.same ? 58 : 110).strength(l =&gt; 0.25 + 0.12 * l.lift))
    .force("charge", d3.forceManyBody().strength(-430))
    .force("collide", d3.forceCollide(52))
    .force("x", d3.forceX(0).strength(0.05))
    .force("y", d3.forceY(0).strength(0.07))
    .stop();
  for (let i = 0; i &lt; 400; i++) sim.tick();
  return {nodes, links};
}







// A function so the visible cell below creates the element itself.
networkChart = () =&gt; {
  const w = chartWidth, h = narrow ? 520 : 600, pad = narrow ? 34 : 60;
  const {nodes, links} = topicNetwork;
  const xs = d3.extent(nodes, d =&gt; d.x), ys = d3.extent(nodes, d =&gt; d.y);
  const sx = d3.scaleLinear(xs, [narrow ? 90 : 130, w - (narrow ? 90 : 130)]);
  const sy = d3.scaleLinear(ys, [pad, h - pad]);
  const r = d =&gt; 5 + d.degree * (narrow ? 1.4 : 1.9);
  const width = d3.scaleLinear([1, 4.6], [1, 6]);
  const focus = bundleView === "All groups" ? null : bundleView;
  const svg = d3.create("svg").attr("viewBox", [0, 0, w, h]).attr("width", w).attr("height", h)
    .attr("role", "img").attr("aria-label", "Network of topics that appear together in low-rated hospital reviews")
    .style("max-width", "100%").style("height", "auto").style("font-family", "inherit");
  const edge = svg.append("g").selectAll("line").data(links).join("line")
    .attr("x1", d =&gt; sx(d.source.x)).attr("y1", d =&gt; sy(d.source.y))
    .attr("x2", d =&gt; sx(d.target.x)).attr("y2", d =&gt; sy(d.target.y))
    .attr("stroke", d =&gt; d.same ? bundleColors.get(d.source.bundle) : C.sub)
    .attr("stroke-width", d =&gt; width(d.lift)).attr("stroke-linecap", "round");
  edge.append("title").text(d =&gt; `${d.source.id} × ${d.target.id}\n${d.lift.toFixed(2)}× expected${d.same ? "" : "\nAcross groups"}`);
  const node = svg.append("g").selectAll("g").data(nodes).join("g")
    .attr("transform", d =&gt; `translate(${sx(d.x)},${sy(d.y)})`).style("cursor", "pointer");
  node.append("circle").attr("r", r).attr("fill", d =&gt; bundleColors.get(d.bundle))
    .attr("stroke", C.bg).attr("stroke-width", 2);
  // Put each label on the side facing away from the node's neighbours.
  const side = new Map(nodes.map(n =&gt; [n.id, 0]));
  links.forEach(l =&gt; { side.set(l.source.id, side.get(l.source.id) + (l.target.x - l.source.x)); side.set(l.target.id, side.get(l.target.id) + (l.source.x - l.target.x)); });
  // Busy hubs get their label above the dot instead.
  const hub = d =&gt; d.degree &gt;= 4;
  const left = d =&gt; side.get(d.id) &gt; 0;
  node.append("text").text(d =&gt; d.id)
    .attr("x", d =&gt; hub(d) ? 0 : left(d) ? -(r(d) + 5) : r(d) + 5)
    .attr("y", d =&gt; hub(d) ? -(r(d) + 6) : 4)
    .attr("text-anchor", d =&gt; hub(d) ? "middle" : left(d) ? "end" : "start")
    .attr("fill", C.ink).attr("font-size", narrow ? 10.5 : 12)
    .attr("paint-order", "stroke").attr("stroke", C.bg).attr("stroke-width", 3);
  node.append("title").text(d =&gt; `${d.id} (${d.bundle})\n${d.degree} retained ${d.degree === 1 ? "pair" : "pairs"}`);

  const partners = new Map(nodes.map(n =&gt; [n.id, new Set([n.id])]));
  links.forEach(l =&gt; { partners.get(l.source.id).add(l.target.id); partners.get(l.target.id).add(l.source.id); });
  function paint(hover) {
    const on = n =&gt; hover ? partners.get(hover).has(n.id) : !focus || n.bundle === focus;
    const onEdge = l =&gt; hover ? (l.source.id === hover || l.target.id === hover) : !focus || l.source.bundle === focus || l.target.bundle === focus;
    node.attr("opacity", d =&gt; on(d) ? 1 : 0.18);
    node.select("text").attr("font-weight", d =&gt; (hover ? d.id === hover : focus && d.bundle === focus) ? 600 : 400);
    edge.attr("opacity", d =&gt; onEdge(d) ? (0.35 + 0.13 * d.lift) : 0.06);
  }
  node.on("pointerenter", (e, d) =&gt; paint(d.id)).on("pointerleave", () =&gt; paint(null));
  paint(null);

  const legend = html`&lt;div class="net-legend"&gt;${topicBundles.map(b =&gt; html`&lt;span&gt;&lt;i style="background:${bundleColors.get(b.name)}"&gt;&lt;/i&gt;${b.name}&lt;/span&gt;`)}&lt;/div&gt;`;
  return html`&lt;div class="net-wrap"&gt;${svg.node()}${legend}&lt;/div&gt;`;
}







